// GetMasterMongoClient returns a cached or newly opened *mongo.Client for a MongoDB master destination.
func (m *ConnectionManager) GetMasterMongoClient(ctx context.Context, key string) (*mongo.Client, error) {
	key = strings.TrimSpace(key)
	if key == "" {
		return nil, fmt.Errorf("master mongo connection key is empty")
	}

	m.masterPoolMu.RLock()
	if client, ok := m.masterMongoPool[key]; ok && client != nil {
		m.masterPoolMu.RUnlock()
		return client, nil
	}
	m.masterPoolMu.RUnlock()

	m.masterPoolMu.Lock()
	defer m.masterPoolMu.Unlock()

	if client, ok := m.masterMongoPool[key]; ok && client != nil {
		return client, nil
	}

	uri, defaultDB := m.resolveMasterMongoURI(ctx, key)
	if uri == "" {
		return nil, fmt.Errorf("mongo master connection URI not found for key %q", key)
	}

	clientOpts := options.Client().ApplyURI(uri)
	client, err := mongo.Connect(ctx, clientOpts)
	if err != nil {
		return nil, fmt.Errorf("connect master mongo for %q: %w", key, err)
	}

	m.masterMongoPool[key] = client
	if defaultDB != "" {
		m.masterMongoDBs[key] = defaultDB
	}
	return client, nil
}

// ResolveMasterMongoDatabase resolves the target MongoDB database name for a master connection key.
func (m *ConnectionManager) ResolveMasterMongoDatabase(ctx context.Context, key, fallbackDB string) string {
	key = strings.TrimSpace(key)
	m.masterPoolMu.RLock()
	if dbName, ok := m.masterMongoDBs[key]; ok && strings.TrimSpace(dbName) != "" {
		m.masterPoolMu.RUnlock()
		return dbName
	}
	m.masterPoolMu.RUnlock()

	_, defaultDB := m.resolveMasterMongoURI(ctx, key)
	if strings.TrimSpace(defaultDB) != "" {
		m.masterPoolMu.Lock()
		m.masterMongoDBs[key] = defaultDB
		m.masterPoolMu.Unlock()
		return defaultDB
	}
	if strings.TrimSpace(fallbackDB) != "" && fallbackDB != "public" {
		return strings.TrimSpace(fallbackDB)
	}
	return "gpay_master"
}

